+func (s *EtcdServer) RangeStream(r *pb.RangeRequest, stream pb.KV_RangeStreamServer) error {
+	ctx := stream.Context()
+	if !r.Serializable {
+		if err := s.read.LinearizableReadNotify(ctx); err != nil {
+			return err
+		}
+	}
+
+	chk := func(ai *auth.AuthInfo) error {
+		return s.authStore.IsRangePermitted(ai, r.Key, r.RangeEnd)
+	}
+
+	var streamErr error
+	get := func() {
+		req := *r
+		total, readRev, err := txn.RangeCount(ctx, s.Logger(), s.KV(), &req)
+		if err != nil {
+			streamErr = err
+			return
+		}
+		if req.Revision <= 0 {
+			req.Revision = readRev
+		}
+
+		finalMore := !req.CountOnly && req.Limit > 0 && total > req.Limit
+		remaining := total
+		if req.Limit > 0 && remaining > req.Limit {
+			remaining = req.Limit
+		}
+		if req.CountOnly || remaining == 0 {
+			streamErr = stream.Send(&pb.RangeStreamResponse{RangeResponse: &pb.RangeResponse{
+				Header: &pb.ResponseHeader{Revision: readRev},
+				More:   finalMore,
+				Count:  total,
+			}})
+			return
+		}
+
+		const initialChunkLimit int64 = 1
+		chunkLimit := initialChunkLimit
+		maxResponseBytes := int64(s.Cfg.MaxRequestBytes)
+		if maxResponseBytes < 1 {
+			maxResponseBytes = 1
+		}
+
+		for remaining > 0 {
+			if err := ctx.Err(); err != nil {
+				streamErr = err
+				return
+			}
+			if chunkLimit > remaining {
+				chunkLimit = remaining
+			}
+			req.Limit = chunkLimit
+			resp, _, err := txn.Range(ctx, s.Logger(), s.KV(), &req, false)
+			if err != nil {
+				streamErr = err
+				return
+			}
+
+			n := int64(len(resp.Kvs))
+			if n == 0 {
+				streamErr = errorspkg.New("range stream made no progress")
+				return
+			}
+			remaining -= n
+			final := remaining == 0
+			if final {
+				resp.Header = &pb.ResponseHeader{Revision: readRev}
+				resp.More = finalMore
+				resp.Count = total
+			} else {
+				resp.Header = nil
+				resp.More = false
+				resp.Count = 0
+			}
+			streamErr = stream.Send(&pb.RangeStreamResponse{RangeResponse: resp})
+			if streamErr != nil {
+				return
+			}
+			if final {
+				return
+			}
+
+			lastKey := resp.Kvs[len(resp.Kvs)-1].Key
+			req.Key = make([]byte, len(lastKey)+1)
+			copy(req.Key, lastKey)
+
+			responseBytes := int64(resp.Size())
+			if responseBytes < 1 {
+				responseBytes = 1
+			}
+			if n > 0 {
+				bytesPerKV := responseBytes / n
+				if bytesPerKV < 1 {
+					bytesPerKV = 1
+				}
+				chunkLimit = maxResponseBytes / bytesPerKV
+				if chunkLimit < 1 {
+					chunkLimit = 1
+				}
+			}
+		}
+	}
+	if err := s.doSerialize(ctx, chk, get); err != nil {
+		return err
+	}
+	return streamErr
+}
